import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

symmetric_matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
constexpr int WARPS_PER_BLOCK = 4;
constexpr int WARP_SIZE = 8;

__global__ void symmetric_matmul_kernel(const float* __restrict__ A,
                                       const float* __restrict__ B,
                                       float* __restrict__ C,
                                       int N) {
    int row = blockIdx.y * TILE_SIZE + threadIdx.y * WARP_SIZE;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x * WARP_SIZE;

    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    float accum[WARP_SIZE][WARP_SIZE] = {0};

    for (int t = 0; t < N; t += TILE_SIZE) {
        // Collaborative loading of A and B tiles using symmetry
        int load_row = t + threadIdx.y * WARP_SIZE + (threadIdx.z * WARP_SIZE);
        int load_col = t + threadIdx.x * WARP_SIZE + (threadIdx.z * WARP_SIZE);

        if (load_row < N && load_col < N) {
            As[threadIdx.y * WARP_SIZE + threadIdx.z][threadIdx.x * WARP_SIZE + threadIdx.z] 
                = A[load_row * N + load_col];
            Bs[threadIdx.y * WARP_SIZE + threadIdx.z][threadIdx.x * WARP_SIZE + threadIdx.z] 
                = B[load_col * N + load_row];  // Utilize symmetry
        }
        __syncthreads();

        // Warp-level matrix multiply-accumulate
        for (int k = 0; k < TILE_SIZE; k++) {
            float a = As[threadIdx.y * WARP_SIZE + threadIdx.z][k];
            float b = Bs[k][threadIdx.x * WARP_SIZE + threadIdx.z];

            for (int i = 0; i < WARP_SIZE; ++i) {
                for (int j = 0; j < WARP_SIZE; ++j) {
                    accum[i][j] += a * b;
                }
            }
        }
        __syncthreads();
    }

    // Store results using symmetry optimization
    for (int i = 0; i < WARP_SIZE; ++i) {
        for (int j = 0; j < WARP_SIZE; ++j) {
            int out_row = row + i;
            int out_col = col + j;
            if (out_row < N && out_col < N) {
                C[out_row * N + out_col] = accum[i][j];
                if (out_row != out_col) {
                    C[out_col * N + out_row] = accum[i][j];  // Mirror using symmetry
                }
            }
        }
    }
}

torch::Tensor symmetric_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);
    dim3 block(WARPS_PER_BLOCK, WARPS_PER_BLOCK, WARPS_PER_BLOCK);

    symmetric_matmul_kernel<<<grid, block>>>(A.data_ptr<float>(),
                                            B.data_ptr<float>(),
                                            C.data_ptr<float>(),
                                            N);
    return C;
}
"""

symmetric_matmul_cpp_source = "torch::Tensor symmetric_matmul_cuda(torch::Tensor A, torch::Tensor B);"

symmetric_matmul = load_inline(
    name='symmetric_matmul',
    cpp_sources=symmetric_matmul_cpp_source,
    cuda_sources=symmetric_matmul_source,
    functions=['symmetric_matmul_cuda'],
    verbose=True,
    extra_cuda_cflags=['-O3', '--use_fast_math']
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        return symmetric_matmul.symmetric_matmul_cuda(A, B)
